gNg(){return"\u0646\u06d5\u062a\u0648\u0627\u0646\u0631\u0627 \u0646\u0627\u0645\u06d5\u06a9\u0627\u0646 \u0628\u0627\u0631 \u0628\u06a9\u0631\u06ce\u0646"},
gNq(){return"\u0647\u06d5\u06b5\u06d5\u06cc\u06d5\u06a9 \u0695\u0648\u0648\u06cc\u062f\u0627. \u062a\u06a9\u0627\u06cc\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0647\u06d5\u0648\u06b5 \u0628\u062f\u06d5\u0631\u06d5\u0648\u06d5."},
gNe(){return"\u06af\u0641\u062a\u0648\u06af\u06c6\u06a9\u06d5 \u067e\u0627\u06a9 \u0628\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5\u061f"},
gNd(){return"\u0626\u06d5\u0645\u06d5 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u0645\u06ce\u0698\u0648\u0648\u06cc \u0695\u0627\u0648\u06ce\u0698\u06cc \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f \u0628\u06c6 \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5 \u062f\u06d5\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5. \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u067e\u0627\u0634\u06af\u06d5\u0632 \u0628\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5."},
gCN(){return"\u067e\u0627\u06a9\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5"},
gNf(){return"\u0646\u06d5\u062a\u0648\u0627\u0646\u0631\u0627 \u0645\u06ce\u0698\u0648\u0648\u06d5\u06a9\u06d5 \u067e\u0627\u06a9 \u0628\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5. \u062a\u06a9\u0627\u06cc\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0647\u06d5\u0648\u06b5 \u0628\u062f\u06d5\u0631\u06d5\u0648\u06d5."},
gCO(){return"\u067e\u0631\u0633\u06cc\u0627\u0631\u06d5 \u067e\u06ce\u0634\u0646\u06cc\u0627\u0631\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646"},
gNr(){return"\u0695\u0627\u0648\u06ce\u0698\u06cc \u0632\u06cc\u0631\u06d5\u06a9\u06cc \u062f\u06d5\u0633\u062a\u06a9\u0631\u062f"},
