ga0K(){return"\u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u0645 \u0686\u0627\u0631\u06d5\u06a9\u06d5 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u06d5 \u06cc\u0627\u0646 \u0644\u0627\u0628\u062f\u06d5"},
gF8(){return"\u06af\u0631\u062a\u0646"},
gPs(){return"\u06af\u0631\u062a\u0646"},
gPr(){return"\u0644\u06ce\u0631\u06d5 \u0648\u06ce\u0646\u06d5\u060c \u06a4\u06cc\u062f\u06cc\u06c6\u060c \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u062f\u06d5\u0646\u06af\u060c \u06cc\u0627\u0646 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u06d5\u06a9 \u0628\u06af\u0631\u06d5 \u2014 \u067e\u0627\u0634\u0627\u0646 \u0628\u06cc\u06a9\u06d5 \u0628\u06d5 \u0647\u0627\u0648\u067e\u06ce\u0686\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06ce\u06a9 \u06cc\u0627\u0646 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u060c \u0644\u06d5 \u0647\u06d5\u0631 \u0626\u0627\u0645\u06ce\u0631\u06ce\u06a9\u06d5\u0648\u06d5."},
gPp(){return"\u06a9\u0627\u0645\u06ce\u0631\u0627"},
