gNE(){return"\u0626\u06d5\u0645 \u0641\u0627\u06cc\u0644\u06d5 \u0628\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5\u061f"},
gND(){return"\u0626\u06d5\u0645\u06d5 \u0628\u06c6 \u0647\u06d5\u062a\u0627\u0647\u06d5\u062a\u0627\u06cc\u06d5 \u0644\u0627\u06cc \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5 \u062f\u06d5\u06cc\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5. \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u067e\u0627\u0634\u06af\u06d5\u0632 \u0628\u06ce\u062a\u06d5\u0648\u06d5."},
gNK(){return"\u067e\u0632\u06cc\u0634\u06a9 \u0628\u06cc\u0646\u06cc\u0648\u06cc\u06d5\u062a\u06cc"},
