gJ7(){return"\u0641\u0627\u06cc\u0644\u06d5\u06a9\u0627\u0646\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0644\u06c6\u06a9\u0627\u0644\u06cc \u0647\u06d5\u06b5\u0628\u06af\u06cc\u0631\u06ce\u062a"},
gJ8(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9 \u0647\u06d5\u0645\u0648\u0648 \u0641\u0627\u06cc\u0644\u06d5\u06a9\u0627\u0646\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06ce\u06a9\u06cc \u0628\u06cc\u0646\u06cc\u060c \u06a9\u06c6\u067e\u06cc\u06d5\u06a9\u0627\u0646\u06cc\u0627\u0646 \u0644\u06d5 \u0647\u06d5\u06b5\u06af\u0631\u062a\u0646 \u0628\u06d5 \u062e\u06c6\u06a9\u0627\u0631 \u067e\u0627\u06a9 \u062f\u06d5\u06a9\u0631\u06ce\u0646\u06d5\u0648\u06d5 \u2014 \u062a\u06c6\u0645\u0627\u0631\u06d5\u06a9\u06d5 \u062f\u06d5\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5\u060c \u0628\u06d5\u06b5\u0627\u0645 \u0646\u0627\u0648\u06d5\u0695\u06c6\u06a9\u06d5\u06a9\u06d5 \u0646\u0627."},
gHP(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u0647\u0627\u0648\u067e\u06ce\u0686 \u0628\u062f\u06d5"},
gHQ(){return"\u06a9\u0644\u06cc\u0644\u06cc \u0633\u06d5\u0631\u06d5\u06a9\u06cc \u2014 \u06a9\u0648\u0698\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u0645\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u0634\u0648\u06ce\u0646\u06ce\u06a9 \u0647\u0627\u0648\u067e\u06ce\u0686\u06a9\u0631\u062f\u0646 \u062f\u06d5\u0634\u0627\u0631\u06ce\u062a\u06d5\u0648\u06d5\u060c \u0633\u06d5\u0631\u0628\u0627\u0631\u06cc \u0686\u0648\u0627\u0631 \u0695\u06ce\u06a9\u062e\u0633\u062a\u0646\u06d5\u06a9\u06d5\u06cc \u062e\u0648\u0627\u0631\u06d5\u0648\u06d5."},
