gI_(){return"\u0628\u06d5 \u0628\u0646\u06d5\u0695\u06d5\u062a \u06a9\u0648\u0698\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5 \u2014 \u06a4\u06cc\u062f\u06cc\u06c6 \u067e\u06ce\u0634 \u0628\u0627\u0631\u06a9\u0631\u062f\u0646 \u067e\u06d5\u0633\u062a\u0627\u0648 \u0646\u0627\u06a9\u0631\u06ce\u062a\u060c \u0628\u06c6\u06cc\u06d5 \u0632\u06c6\u0631 \u0632\u06cc\u0627\u062a\u0631 \u0644\u06d5 \u0648\u06ce\u0646\u06d5 \u0634\u0648\u06ce\u0646 \u0648 \u062f\u0627\u062a\u0627 \u0628\u06d5\u06a9\u0627\u0631\u062f\u06d5\u0647\u06ce\u0646\u06ce\u062a."},
gHR(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u062f\u06d5\u0646\u06af \u0628\u062f\u06d5"},
gHS(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0646\u0627\u0645\u06d5\u06cc \u062f\u06d5\u0646\u06af\u06cc."},
gHT(){return"\u0695\u06ce\u06af\u06d5 \u0628\u06d5 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5 \u0628\u062f\u06d5"},
gHU(){return"\u0647\u0627\u0648\u067e\u06ce\u0686\u06cc \u062c\u06c6\u0631\u06cc PDF/\u0633\u06a9\u0627\u0646 \u2014 \u0641\u06c6\u0631\u0645\u06cc \u0628\u06cc\u0645\u06d5\u060c \u0646\u0627\u0645\u06d5\u06cc \u0646\u0627\u0631\u062f\u0646 \u0648 \u0647\u062a\u062f."},
