gMR(){return"\u0695\u06c6\u0698\u06cc \u062a\u06d5\u0648\u0627\u0648"},
gCG(){return"\u0646\u06cc\u0648 \u0695\u06c6\u0698"},
gMJ(){return"\u0644\u06d5 \u0645\u0648\u0648\u0686\u06d5 \u0628\u0628\u0695\u062f\u0631\u06ce\u062a"},
gMI(){return"\u0646\u06cc\u0634\u0627\u0646\u06d5\u06a9\u06d5 \u0644\u0627\u0628\u06d5 \u0626\u06d5\u06af\u06d5\u0631 \u0645\u06c6\u06b5\u06d5\u062a\u06cc \u0628\u06d5 \u0645\u0648\u0648\u0686\u06d5 \u0628\u06ce\u062a"},
gMS(){return"\u062a\u06ce\u0628\u06cc\u0646\u06cc (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gMV(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u063a\u06cc\u0627\u0628"},
gMT(){return"\u0626\u06d5\u0645 \u0628\u06d5\u0631\u0648\u0627\u0631\u06d5 \u06cc\u06d5\u06a9\u06ce\u06a9\u06d5 \u0644\u06d5 \u0695\u06c6\u0698\u0627\u0646\u06cc \u067e\u0634\u0648\u0648\u06cc \u0647\u06d5\u0641\u062a\u0627\u0646\u06d5\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u06d5\u062a."},
gMN(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u063a\u06cc\u0627\u0628\u06ce\u06a9 \u062a\u06c6\u0645\u0627\u0631 \u0646\u06d5\u06a9\u0631\u0627\u0648\u06d5."},
gMU(){return"\u0645\u06c6\u06b5\u06d5\u062a\u06cc \u0628\u06d5 \u0645\u0648\u0648\u0686\u06d5"},
gML(){return"\u063a\u06cc\u0627\u0628\u06d5\u06a9\u06d5 \u0628\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5\u061f"},
MK(a){return"\u063a\u06cc\u0627\u0628\u06cc \u0695\u06c6\u0698\u06cc "+a+" \u062f\u06d5\u0633\u0695\u062f\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u0648 \u0645\u0648\u0648\u0686\u06d5\u06cc \u0626\u06d5\u0648 \u0645\u0627\u0646\u06af\u06d5 \u0646\u0648\u06ce \u062f\u06d5\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5."},
gMO(){return"\u0645\u0648\u0648\u0686\u06d5\u06cc \u0626\u06d5\u0648 \u0645\u0627\u0646\u06af\u06d5 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u0631\u0627\u0648\u06d5\u060c \u0628\u06c6\u06cc\u06d5 \u0647\u06cc\u0686\u06cc \u0646\u06d5\u0645\u0627\u0648\u06d5 \u0628\u06c6 \u0628\u0695\u06cc\u0646. \u0648\u06d5\u06a9 \u0645\u06c6\u06b5\u06d5\u062a\u06cc \u0628\u06d5 \u0645\u0648\u0648\u0686\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06cc \u0628\u06a9\u06d5\u060c \u06cc\u0627\u0646 \u0633\u06d5\u0631\u06d5\u062a\u0627 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06ce\u06a9\u06cc \u0645\u0648\u0648\u0686\u06d5 \u0628\u0633\u0695\u06d5\u0648\u06d5."},
CH(a){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a \u0646\u06d5\u06a9\u0631\u0627: "+a},
MX(a){return"\u06a9\u0631\u06ce\u06cc \u06cc\u06d5\u06a9 \u0695\u06c6\u0698 = \u0645\u0648\u0648\u0686\u06d5\u06cc \u0645\u0627\u0646\u06af\u0627\u0646\u06d5 \xf7 "+a},
