QL(a){return a+" \u0686\u06cc\u062a\u0631 \u0648\u06d5\u06b5\u0627\u0645 \u0646\u0627\u062f\u0627\u062a\u06d5\u0648\u06d5 \u0648 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5\u06a9\u0627\u0646\u06cc \u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0633\u0695\u062f\u0631\u06ce\u0646\u06d5\u0648\u06d5. \u0646\u06d5\u062e\u06c6\u0634 \u0648 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u06a9\u0627\u0631\u06cc\u06af\u06d5\u0631 \u0646\u0627\u0628\u0646."},
gYc(){return"\u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u06a9\u0627\u062a \u0628\u06d5 \u0626\u06c6\u0646\u0644\u0627\u06cc\u0646"},
gY1(){return"\u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u0627\u0646 \u062e\u06c6\u06cc\u0627\u0646 \u06a9\u0627\u062a\u06ce\u06a9\u06cc \u0628\u06d5\u062a\u0627\u06b5 \u0647\u06d5\u06b5\u062f\u06d5\u0628\u0698\u06ce\u0631\u0646\u060c \u0644\u06d5 \u067e\u06d5\u0695\u06d5\u06cc \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u06a9\u0627\u062a\u06d5\u06a9\u06d5\u062a \u0648 \u0644\u06d5 \u0628\u06c6\u062a\u06cc \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06d5\u06a9\u06d5\u062a. \u06a9\u0627\u062a\u06d5 \u0628\u06d5\u062a\u0627\u06b5\u06d5\u06a9\u0627\u0646 \u0628\u06d5\u067e\u06ce\u06cc \u06a9\u0627\u062a\u06cc \u06a9\u0627\u0631\u06cc \u0647\u06d5\u0631 \u067e\u0632\u06cc\u0634\u06a9\u06ce\u06a9 \u0648 \u0626\u06d5\u0648 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u0627\u0646\u06d5\u06cc \u0647\u06d5\u0646 \u062f\u06d5\u0628\u0646."},
gXZ(){return"\u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06cc \u06a9\u0627\u062a \u0628\u06d5 \u0626\u06c6\u0646\u0644\u0627\u06cc\u0646"},
gY2(){return"\u067e\u06d5\u0695\u06d5\u06cc \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u06a9\u0627\u062a\u06d5\u06a9\u06d5\u062a"},
