gXQ(){return"\u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5\u06a9\u06d5 \u06a9\u06c6\u067e\u06cc \u06a9\u0631\u0627"},
gY3(){return"\u0644\u06d5 \u0646\u0627\u0645\u06d5\u06cc \u0628\u06d5\u062e\u06ce\u0631\u0647\u0627\u062a\u0646\u06cc \u0648\u0627\u062a\u0633\u0626\u06d5\u067e\u060c \u0628\u0627\u06cc\u06c6\u06cc \u0626\u06cc\u0646\u0633\u062a\u0627\u06af\u0631\u0627\u0645 \u0648 \u067e\u06d5\u0695\u06d5\u06cc \u0641\u06d5\u06cc\u0633\u0628\u0648\u0648\u06a9\u06d5\u06a9\u06d5\u062a \u062f\u0627\u06cc\u0628\u0646\u06ce."},
gYb(){return"\u0645\u0627\u0648\u06d5\u06cc \u0647\u06d5\u0631 \u06a9\u0627\u062a\u06ce\u06a9"},
Fq(a){return""+a+" \u062e\u0648\u0644\u06d5\u06a9"},
gY8(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0644\u06d5 \u0647\u06d5\u0631 \u06a9\u0627\u062a\u06ce\u06a9\u062f\u0627"},
gXV(){return"\u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646 \u062a\u0627"},
XU(a){return""+a+" \u0695\u06c6\u0698 \u067e\u06ce\u0634\u062a\u0631"},
