gXS(){return"\u067e\u0634\u0648\u0648"},
gXN(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0645\u0627\u0648\u06d5\u06cc\u06d5\u06a9"},
