MM(a){return"\u0646\u06d5\u0647\u0627\u062a\u0646 \u2014 "+a},
gMH(){return"\u062f\u06cc\u0631\u06c6\u06a9"},
gMR(){return"\u0631\u06c6\u0698\u06d5\u06a9\u0627 \u062a\u06d5\u0645\u0627\u0645"},
gCG(){return"\u0646\u06cc\u06a4 \u0631\u06c6\u0698"},
