gMS(){return"\u062a\u06ce\u0628\u06cc\u0646\u06cc (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gMV(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u0627 \u0646\u06d5\u0647\u0627\u062a\u0646\u06ce"},
gMT(){return"\u0626\u06d5\u06a4 \u062f\u06cc\u0631\u06c6\u06a9\u06d5 \u0626\u06ce\u06a9 \u0698 \u0631\u06c6\u0698\u06ce\u0646 \u067e\u0634\u0648\u0648\u06cc\u0627 \u0647\u06d5\u0641\u062a\u06cc\u0627\u0646\u06d5 \u06cc\u0627 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u0627 \u062a\u06d5\u06cc\u06d5."},
gMN(){return"\u0647\u06ce\u0634\u062a\u0627 \u0686 \u0646\u06d5\u0647\u0627\u062a\u0646 \u0646\u06d5\u0647\u0627\u062a\u06cc\u0646\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646."},
gMU(){return"\u0645\u06c6\u0644\u06d5\u062a\u0627 \u0628 \u067e\u0627\u0631\u06d5"},
gML(){return"\u0646\u06d5\u0647\u0627\u062a\u0646\u06ce \u0698\u06ce\u0628\u0628\u06d5\u06cc\u061f"},
MK(a){return"\u0646\u06d5\u0647\u0627\u062a\u0646\u0627 "+a+" \u062f\u06ce \u0647\u06ce\u062a\u06d5 \u0644\u0627\u062f\u0627\u0646 \u0648 \u0645\u0648\u0648\u0686\u06ce \u0648\u06ce \u0647\u06d5\u06cc\u06a4\u06ce \u062f\u06ce \u0647\u06ce\u062a\u06d5 \u0646\u0648\u0648\u06a9\u0631\u0646."},
gMO(){return"\u0645\u0648\u0648\u0686\u06ce \u0648\u06ce \u0647\u06d5\u06cc\u06a4\u06ce \u0628 \u062a\u06d5\u0645\u0627\u0645\u06cc \u0647\u0627\u062a\u06cc\u06d5 \u062f\u0627\u0646\u060c \u0644\u06d5\u0648\u0645\u0627 \u0686 \u0646\u06d5\u0645\u0627\u06cc\u06d5 \u0628\u06c6 \u06a9\u06ce\u0645\u06a9\u0631\u0646\u06ce. \u0648\u06d5\u06a9 \u0645\u06c6\u0644\u06d5\u062a\u0627 \u0628 \u067e\u0627\u0631\u06d5 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5\u060c \u06cc\u0627\u0646 \u067e\u06ce\u0634\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u0627 \u0645\u0648\u0648\u0686\u06d5\u06cc \u0698\u06ce\u0628\u0628\u06d5."},
CH(a){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646 \u0633\u06d5\u0631\u0646\u06d5\u06a9\u06d5\u0641\u062a: "+a},
MX(a){return"\u0645\u0648\u0648\u0686\u06ce \u0631\u06c6\u0698\u06d5\u06a9\u06ce = \u0645\u0648\u0648\u0686\u06ce \u0647\u06d5\u06cc\u06a4\u0627\u0646\u06d5 \xf7 "+a},
