gQK(){return"\u06a9\u06c6\u067e\u06cc"},
gQJ(){return"\u0647\u0627\u062a\u06d5 \u06a9\u06c6\u067e\u06cc\u06a9\u0631\u0646"},
QS(a,b){return"\u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u06af\u0631\u06ce\u062f\u0627\u06cc\u06cc: "+a+" \xb7 \u0626\u06d5\u06a9\u0627\u0648\u0646\u062a\u06ce\u0646 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce: "+b},
gQR(){return"\u06a4\u06cc \u0644\u06cc\u0646\u06a9\u06cc \u0628\u06c6 \u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u062e\u06c6 \u0628\u0641\u0631\u06ce\u06a9\u06d5 (\u0648\u0627\u062a\u0633\u0627\u067e\u060c \u067e\u06c6\u0633\u062a\u06d5\u0631\u06d5\u06a9 \u0644 \u067e\u06ce\u0634\u0648\u0627\u0632\u06cc\u06ce). Start \u062f\u0627\u062f\u06af\u0631\u0646 \u0648 \u0698\u0645\u0627\u0631\u0627 \u062a\u06d5\u0644\u06d5\u0641\u06c6\u0646\u0627 \u062e\u06c6 \u067e\u0627\u0631\u06a4\u06d5 \u062f\u06a9\u06d5\u0646\u061b \u0628\u06c6\u062a \u0628 \u0648\u06ce \u0698\u0645\u0627\u0631\u0627 \u0644 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u06cc \u0641\u0627\u06cc\u0644\u0627 \u0648\u0627\u0646 \u062f\u0628\u06cc\u0646\u06cc\u062a."},
